steps.action:
curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": {
      "issues": {
        "filter": {
          "title": { "contains": "Renew SSO certificate" }
        },
        "first": 10
      } {
        nodes {
          id
          title
          priority
          assignee {
            id
            name
            email
          }
          creator {
            id
            name
            email
          }
          team {
            id
            name
          }
        }
      }
    }
  }'
